#include <fstream>
#include <iostream>
#include <iterator>
#include <string>
#include <ptx_frontend/resolved_ir/ptx_resolved_ir.hpp>
#include <ptx_frontend/syntax/ptx_syntax_parser.hpp>

/** Check one PTX 8.0/sm_80 module; distinct exits expose parse/resolve failures. */
int main(int argc, char** argv) {
  using namespace ptx_frontend;
  using namespace ptx_frontend::resolved_ir;
  if (argc != 2) return 4;
  std::ifstream input(argv[1]);
  if (!input) return 4;
  const std::string source{std::istreambuf_iterator<char>{input}, {}};
  PtxSyntaxParser parser(source);
  const auto ast = parser.parseModule();
  if (!ast || !ast.diagnostics.empty()) return 2;
  const auto module = resolveModule(*ast);
  if (!module) {
    for (const auto& diagnostic : module.error())
      std::cout << (diagnostic.checker_kind ? "checker: " : "resolution: ")
                << diagnostic.message << '\n';
    return 3;
  }
  const checker::Context context{.target = {.ptx_version = {8, 0}, .sm_version = 80}};
  bool valid = true;
  for (const auto& function : module->functions) {
    for (const auto& instruction : function.body) {
      const auto checked = std::visit(
          [&context](const auto& value) { return checker::check(value, context); },
          instruction);
      if (!checked) {
        valid = false;
        for (const auto& diagnostic : checked.error())
          std::cout << diagnostic.message << '\n';
      }
    }
  }
  return valid ? 0 : 1;
}

